import json
from collections import Counter

def find_separators(grid, bg_color):
    """Find uniform rows and cols that differ from bg_color"""
    rows, cols = len(grid), len(grid[0])
    seed_rows = []
    seed_cols = []

    for r in range(rows):
        if len(set(grid[r])) == 1:
            if grid[r][0] != bg_color:  # uniform but not background
                seed_rows.append(r)

    for c in range(cols):
        col_vals = [grid[r][c] for r in range(rows)]
        if len(set(col_vals)) == 1:
            if col_vals[0] != bg_color:  # uniform col but not background
                seed_cols.append(c)

    return seed_rows, seed_cols

def find_regions(rows, cols, seed_rows, seed_cols):
    """Return list of (row_start, row_end, col_start, col_end) for each region"""
    regions = []

    # Sort seeds
    seed_rows = sorted(seed_rows)
    seed_cols = sorted(seed_cols)

    # Find row ranges
    row_ranges = []
    r = 0
    for sr in seed_rows:
        if r < sr:
            row_ranges.append((r, sr - 1))
        r = sr + 1
    if r < rows:
        row_ranges.append((r, rows - 1))

    # Find col ranges
    col_ranges = []
    c = 0
    for sc in seed_cols:
        if c < sc:
            col_ranges.append((c, sc - 1))
        c = sc + 1
    if c < cols:
        col_ranges.append((c, cols - 1))

    # Combine
    for rstart, rend in row_ranges:
        for cstart, cend in col_ranges:
            if rstart <= rend and cstart <= cend:
                regions.append((rstart, rend, cstart, cend))

    return regions

def solve(grid):
    # Count colors to find background
    colors = Counter()
    for row in grid:
        for cell in row:
            colors[cell] += 1
    bg_color = sorted(colors.keys(), key=lambda x: -colors[x])[0]

    # Find seed rows and cols
    seed_rows, seed_cols = find_separators(grid, bg_color)

    # Find regions
    regions = find_regions(len(grid), len(grid[0]), seed_rows, seed_cols)

    # Find pattern region (the one with most non-background cells)
    max_pattern_region = -1
    max_pattern_count = 0

    for i, (rstart, rend, cstart, cend) in enumerate(regions):
        count = 0
        for r in range(rstart, rend + 1):
            for c in range(cstart, cend + 1):
                if grid[r][c] != bg_color:
                    count += 1
        if count > max_pattern_count:
            max_pattern_count = count
            max_pattern_region = i

    # The pattern region
    rstart_p, rend_p, cstart_p, cend_p = regions[max_pattern_region]

    # Create output copy of input
    output = [row[:] for row in grid]

    # For each non-pattern region, copy the pattern at same relative position
    for i, (rstart, rend, cstart, cend) in enumerate(regions):
        if i == max_pattern_region:
            continue

        # For each cell in this output region
        for r in range(rstart, rend + 1):
            for c in range(cstart, cend + 1):
                # Same relative position in pattern region
                pr = r - rstart
                pc = c - cstart

                # Check if this position has non-bg in pattern region
                if rstart_p <= rstart + pr and cstart_p <= cstart + pc:
                    pat_cell = grid[rstart + pr][cstart + pc]
                    if pat_cell != bg_color:
                        output[r][c] = pat_cell

    return output

